-- Dramora Phase 1: identity and project ownership foundation.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_asset_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete restrict,name text not null check(char_length(trim(name)) between 1 and 120),description text not null default '',status text not null default 'active' check(status in ('active','archived')),settings_json jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.project_members(project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('owner','editor','viewer')),created_at timestamptz not null default now(),primary key(project_id,user_id));
create index if not exists projects_owner_updated_idx on public.projects(owner_id,updated_at desc);
create index if not exists project_members_user_idx on public.project_members(user_id,project_id);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end; $$;
create or replace function public.is_project_member(target_project_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.project_members pm where pm.project_id=target_project_id and pm.user_id=(select auth.uid())); $$;
create or replace function public.has_project_role(target_project_id uuid,allowed_roles text[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.project_members pm where pm.project_id=target_project_id and pm.user_id=(select auth.uid()) and pm.role=any(allowed_roles)); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,nullif(trim(coalesce(new.raw_user_meta_data->>'display_name','')),'')) on conflict(id) do nothing;return new;end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at before update on public.profiles for each row execute procedure public.set_updated_at();
drop trigger if exists projects_set_updated_at on public.projects;
create trigger projects_set_updated_at before update on public.projects for each row execute procedure public.set_updated_at();
create or replace function public.add_project_owner_membership() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.project_members(project_id,user_id,role) values(new.id,new.owner_id,'owner') on conflict(project_id,user_id) do nothing;return new;end; $$;
drop trigger if exists projects_add_owner_membership on public.projects;
create trigger projects_add_owner_membership after insert on public.projects for each row execute procedure public.add_project_owner_membership();
alter table public.profiles enable row level security;
alter table public.projects enable row level security;
alter table public.project_members enable row level security;
create policy profiles_select_self on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy profiles_insert_self on public.profiles for insert to authenticated with check(id=(select auth.uid()));
create policy profiles_update_self on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy projects_select_members on public.projects for select to authenticated using(public.is_project_member(id));
create policy projects_insert_owner on public.projects for insert to authenticated with check(owner_id=(select auth.uid()));
create policy projects_update_editors on public.projects for update to authenticated using(public.has_project_role(id,array['owner','editor'])) with check(public.has_project_role(id,array['owner','editor']));
create policy projects_delete_owner on public.projects for delete to authenticated using(public.has_project_role(id,array['owner']));
create policy project_members_select_project on public.project_members for select to authenticated using(user_id=(select auth.uid()) or public.is_project_member(project_id));
-- Membership writes are intentionally reserved for trusted server-side invitation flows.
grant select,insert,update on public.profiles to authenticated;
grant select,insert,update,delete on public.projects to authenticated;
grant select on public.project_members to authenticated;
revoke all on function public.is_project_member(uuid) from public;
revoke all on function public.has_project_role(uuid,text[]) from public;
grant execute on function public.is_project_member(uuid) to authenticated;
grant execute on function public.has_project_role(uuid,text[]) to authenticated;
